patch.diff:
--- a/src/Target.sol
+++ b/src/Target.sol
@@ -21,11 +21,12 @@
         uint256 amount = stakeOf[msg.sender];
         require(amount > 0, "no position");

-        // Deliberate reentrancy bug: state is cleared after the external call.
-        (bool ok, ) = msg.sender.call{value: amount}("");
-        require(ok, "eth transfer failed");
+          // Effects: update state before external call to prevent reentrancy.
+          totalStaked -= amount;
+          stakeOf[msg.sender] = 0;

-        totalStaked -= amount;
-        stakeOf[msg.sender] = 0;
+          // Interaction: transfer ether after state changes.
+          (bool ok, ) = msg.sender.call{value: amount}("");
+          require(ok, "eth transfer failed");
     }
 }

